					if (c === 13 && me.selected) { // Enter
						evt.preventDefault();
						me.select(undefined, undefined, evt);
					}
					else if (c === 9) { // Tab
						if (me.selected && me.tabSelect) {
							evt.preventDefault();
							me.select(undefined, undefined, evt);
						} else {
							me.close({ reason: "tab" });
						}
					}
					else if (c === 27) { // Esc
						me.close({ reason: "esc" });
